package thaumcraft.test;
import java.nio.file.*;
import java.util.*;
import net.minecraft.client.Minecraft;
import net.minecraftforge.api.distmarker.Dist;
import net.minecraftforge.fml.common.Mod;
import net.minecraftforge.eventbus.api.listener.SubscribeEvent;
import net.minecraftforge.event.TickEvent;
import thaumcraft.client.*;
import thaumcraft.research.*;
@Mod.EventBusSubscriber(modid="thaumcraft",value=Dist.CLIENT)
public final class BookCompletionClient {
 static boolean initial,pages,hidden,icons,searched,image,separator,viewsChecked;static Set<Integer> scales=new HashSet<>();static int scale;static Set<String> recipes=new HashSet<>(),layouts=new HashSet<>();
 static void check(boolean ok,String message){if(!ok)throw new AssertionError(message);}
 @SubscribeEvent public static void tick(TickEvent.ClientTickEvent.Post e)throws Exception{if(!System.getProperty("thaumcraft.bookProbe","").equals("book-complete-client")||!BookCompletionScene.ready)return;var mc=Minecraft.getInstance();if(Files.exists(Path.of("../work/book70-scale"))){int next=Integer.parseInt(Files.readString(Path.of("../work/book70-scale")).trim());if(next!=scale){scale=next;mc.options.guiScale().set(scale);mc.getWindow().setGuiScale(scale);mc.resizeGui();return;}}if(!(mc.gui.screen() instanceof ResearchScreen s)||!s.getMenu().validData())return;var menu=s.getMenu();if(!initial&&s.mapView()&&!BookCompletionScene.expanded){int chapters=0;for(int c=0;c<7;c++)if(menu.categoryUnlocked(c))chapters++;check(chapters==1&&s.visibleTopics()==3,"Fresh book reveals undiscovered chapters/topics");initial=true;thaumcraft.Thaumcraft.LOGGER.info("BOOK70_INITIAL_OK: fresh knowledge, Basics only");}if(initial&&!BookCompletionScene.expanded&&s.mapView()&&s.searchQuery().equals("infusion")&&s.searchMatches()==0&&!hidden){hidden=true;thaumcraft.Thaumcraft.LOGGER.info("BOOK70_HIDDEN_OK: no search results without visible matching research");}if(!s.mapView()){check(s.readerLayoutFits(),"Reader controls/text outside margins: "+s.layoutDescription());if(layouts.add(s.layoutDescription()))thaumcraft.Thaumcraft.LOGGER.info("BOOK70_LAYOUT_OK: {}",s.layoutDescription());if(!pages&&!BookCompletionScene.expanded){check(menu.stage(menu.selected())==1&&!menu.ready(),"Reader bypassed unpaid progression");pages=true;thaumcraft.Thaumcraft.LOGGER.info("BOOK70_PAGES_OK: Spanish requirements retain server gate");}if(scales.add(mc.getWindow().getGuiScale()))thaumcraft.Thaumcraft.LOGGER.info("BOOK70_SCALE_{}_OK: {}",mc.getWindow().getGuiScale(),s.layoutDescription());if(s.showingTextPart(BookMarkup.Kind.IMAGE)&&!image){image=true;thaumcraft.Thaumcraft.LOGGER.info("BOOK70_IMAGE_OK: original inline illustration visible");}if((s.showingTextPart(BookMarkup.Kind.LINE)||s.showingTextPart(BookMarkup.Kind.DIVIDER))&&!separator){separator=true;thaumcraft.Thaumcraft.LOGGER.info("BOOK70_SEPARATOR_OK: original separator visible");}for(String key:s.shownRecipes())if(!key.isEmpty()&&recipes.add(key)){var view=BookRecipes.get(key);thaumcraft.Thaumcraft.LOGGER.info("BOOK70_RECIPE_OK: {}",key);if(view!=null&&view.has("layers")){for(var part:view.getAsJsonObject("palette").entrySet())check(!BookRecipes.stack(part.getValue()).isEmpty(),"Empty structure material "+part);thaumcraft.Thaumcraft.LOGGER.info("BOOK70_BLUEPRINT_OK: {}",key);}if(key.startsWith("thaumcraft:diagram/label_")){check(!thaumcraft.alchemy.AlchemyContent.aspect(BookRecipes.result(view)).isEmpty(),"Encoded label lost native aspect");thaumcraft.Thaumcraft.LOGGER.info("BOOK70_LABEL_OK: native encoded label recipe");}}}if(BookCompletionScene.expanded&&s.mapView()&&s.searchQuery().equals("infusion")&&!searched){check(s.searchMatches()>0,"Search cannot find discovered Spanish research");searched=true;thaumcraft.Thaumcraft.LOGGER.info("BOOK70_SEARCH_OK: accent-insensitive query finds discovered topics across chapters");}if(!viewsChecked){var referenced=new HashSet<String>();for(var topic:ResearchCatalog.ENTRIES){for(var st:topic.stages())referenced.addAll(st.recipes());for(var add:topic.addenda())referenced.addAll(add.recipes());}int count=0;for(var ref:referenced)for(var key:BookRecipes.expand(ref)){var view=BookRecipes.get(key);check(view!=null,"Unresolved referenced recipe "+key);check(!BookRecipes.result(view).isEmpty(),"Empty native result "+key);if(view.has("palette"))for(var part:view.getAsJsonObject("palette").entrySet())check(!BookRecipes.stack(part.getValue()).isEmpty(),"Missing blueprint material "+key);count++;}viewsChecked=true;thaumcraft.Thaumcraft.LOGGER.info("BOOK70_REFERENCED_VIEWS_OK: {} expanded native recipe/process results",count);}if(BookCompletionScene.expanded&&!icons){for(var topic:ResearchAtlas.TOPICS.values())for(var icon:topic.icons())if(!icon.has("texture"))check(!BookRecipes.stack(icon).isEmpty(),"Missing topic icon "+topic.key());icons=true;thaumcraft.Thaumcraft.LOGGER.info("BOOK70_ICONS_OK: all original research icons resolved");}}
}
